<section><h1>Permissions</h1><p>The permission catalog is system-managed.</p><div class="table-wrap"><table><thead><tr><th>Module</th><th>Action</th><th>Permission</th><th></th></tr></thead><tbody><?php foreach (($result['items'] ?? array()) as $permission): ?><tr><td><?= dts_escape($permission['module_label']) ?></td><td><?= dts_escape($permission['action_label']) ?></td><td><?= dts_escape($permission['permission_name']) ?></td><td><a href="<?= dts_escape(site_url('permissions/view/'.$permission['permission_id'])) ?>">View</a></td></tr><?php endforeach; ?></tbody></table></div></section>
